
/* Android presentation module: phone-layout-theme-base */
/* Canonical v016 theme: historical patch CSS is not a bundle input.
   Shared page/content/actions geometry belongs to phone-board-layout.css. */
@layer phone-board-foundation;
/* Phone gameplay has no persistent music shortcut. Keep the original audio
   engine and the existing settings inside the map tools untouched. */
@layer phone-board-foundation {
  html[data-platform="android"][data-game-ui^="board"] .board-audio--floating,
  html[data-platform="android"][data-game-ui="board-start"] .page>[data-board-audio-controls] {
    display:none!important;
  }
}
/* Retained art and internal screen presentation: game-mobile */
html[data-platform="android"] {
  --android-vh:100dvh;
  --android-vw:100vw;
  --android-pad:8px;
  --android-panel:linear-gradient(145deg,#0b2536f7,#04111cf7);
  --android-line:#cfa65680;
  -webkit-text-size-adjust:100%;
}
html[data-platform="android"] body {
  min-width:0!important; min-height:0!important;
  width:100%!important; margin:0!important;
  -webkit-tap-highlight-color:rgba(226,191,102,.22);
}
html[data-platform="android"] *, html[data-platform="android"] *::before, html[data-platform="android"] *::after { box-sizing:border-box; }
html[data-platform="android"] * { scroll-behavior:auto!important; }
html[data-platform="android"] [hidden] { display:none!important; }
html[data-platform="android"] button, html[data-platform="android"] select, html[data-platform="android"] summary { touch-action:manipulation; }
html[data-platform="android"] input:not([type="range"]):not([type="checkbox"]), html[data-platform="android"] textarea, html[data-platform="android"] select {
  font-size:16px; min-height:42px; max-width:100%;
}
html[data-platform="android"] button:focus-visible { outline:2px solid #ffe7a6; outline-offset:2px; }
html[data-platform="android"] #androidGameHint {
  position:fixed; z-index:2147483000; bottom:max(8px,env(safe-area-inset-bottom)); left:50%; transform:translateX(-50%);
  width:max-content; max-width:calc(100vw - 32px); padding:9px 14px; border:1px solid #d8b062; border-radius:10px;
  color:#fff4d7; background:#06111df5; font:14px/1.4 system-ui,sans-serif; pointer-events:none;
}
