/* Android presentation module: phone-board-layout */
/* Common Board phone page geometry. Page, content, source regions and actions
   each have one layout owner;
   art and each source screen's internal structure remain in the theme. */
@layer phone-board-foundation {
  html[data-platform="android"][data-game-ui="board"] #boardModal[data-phone-shell="page"] {
    position:fixed!important; inset:0!important; width:var(--android-vw)!important;
    height:var(--android-vh)!important; min-width:0!important; min-height:0!important;
    max-width:none!important; max-height:none!important; margin:0!important; padding:0!important;
    display:grid!important; grid-template-columns:minmax(0,1fr)!important;
    grid-template-rows:minmax(0,1fr)!important; gap:0!important;
    align-items:stretch!important; justify-items:stretch!important;
    overflow:hidden!important; box-sizing:border-box!important;
    transform:none!important; translate:none!important; rotate:none!important; scale:none!important;
    isolation:isolate!important; z-index:0!important;
  }
  html[data-platform="android"][data-game-ui="board"] #boardModal[data-phone-shell="page"]:has(>[data-phone-slot="actions"]) {
    grid-template-rows:minmax(0,1fr) auto!important;
  }
  html[data-platform="android"][data-game-ui="board"] #boardModal[data-phone-shell="page"]>[data-phone-slot="content"] {
    position:relative!important; inset:auto!important; display:block!important;
    grid-column:1!important; grid-row:1!important; width:100%!important; height:auto!important;
    min-width:0!important; min-height:0!important; max-width:none!important; max-height:none!important;
    margin:0!important; padding:0!important; overflow:auto!important;
    box-sizing:border-box!important; overscroll-behavior:contain!important; touch-action:pan-y!important;
    transform:none!important; translate:none!important; z-index:0!important;
  }
  /* The registered original heading, metadata and navigation use natural
     tracks. The original screen receives their remaining space exactly once.
     Source decorations are outside these flow regions. */
  html[data-platform="android"][data-game-ui="board"] #boardModal[data-phone-shell="page"]>[data-phone-slot="content"][data-phone-layout="regions"] {
    display:grid!important; grid-template-columns:minmax(0,1fr)!important;
    grid-template-rows:var(--phone-content-rows,minmax(0,1fr))!important; gap:4px!important;
    align-items:stretch!important; overflow:hidden!important;padding:12px!important;
  }
  html[data-platform="android"][data-game-ui="board"] #boardModal[data-phone-shell="page"]>[data-phone-slot="content"][data-phone-layout="regions"]>[data-phone-region] {
    position:relative!important;inset:auto!important;grid-column:1!important;
    grid-row:var(--phone-region-row)!important;min-width:0!important;min-height:0!important;
    width:100%!important;height:auto!important;max-width:none!important;max-height:none!important;
    margin:0!important;align-self:stretch!important;box-sizing:border-box!important;
    transform:none!important;translate:none!important;rotate:none!important;scale:none!important;
  }
  html[data-platform="android"][data-game-ui="board"] #boardModal[data-phone-shell="page"]>[data-phone-slot="actions"] {
    position:relative!important; inset:auto!important; display:block!important;
    grid-column:1!important; grid-row:2!important; width:100%!important; height:auto!important;
    min-width:0!important; min-height:60px!important; max-width:none!important;
    max-height:40vh!important; margin:0!important; padding:6px 12px!important;
    overflow:auto!important; overscroll-behavior:contain!important; touch-action:pan-y!important;
    box-sizing:border-box!important; transform:none!important; translate:none!important; z-index:1!important;
  }
  html[data-platform="android"][data-game-ui="board"] #boardModal[data-phone-shell="page"]>[data-phone-slot][hidden] {
    display:none!important;
  }
}


/* Android presentation module: board-phone-battle-layout */
/* Battle scroll contract. #infoContent is a source-owned, persistent element;
   original renderers replace its children every 1200 ms. Reading a page must
   therefore scroll this element, never a short-lived descendant. Artwork,
   actor/HUD geometry, source callbacks and the compact GBA strip stay native. */
@layer phone-board-foundation {
  /* Inactive cinematics were opacity-hidden while their full-screen children
     still animated. Keep their DOM and source lifecycle; render on activation. */
  html[data-platform="android"][data-game-ui="board-battle"] .tot-musica-dual-fx:not(.show):not(.leaving),
  html[data-platform="android"][data-game-ui="board-battle"] .raid-phase-fx:not(.show) {
    visibility:hidden;
  }
  /* Keep layout available during viewport changes; skip only inactive motion. */
  html[data-platform="android"][data-game-ui="board-battle"] .tot-musica-dual-fx:not(.show):not(.leaving) *,
  html[data-platform="android"][data-game-ui="board-battle"] .raid-phase-fx:not(.show) * {
    animation-play-state:paused !important;
  }
  html[data-platform="android"][data-game-ui="board-battle"] :is(#playerPortrait,#enemyPortrait),
  html[data-platform="android"][data-game-ui="board-battle"] :is(#playerPortraitWrap,#enemyPortraitWrap) > :is(.board-character-depth-model-layer,.board-character-depth-model-backplate) {
    will-change:transform,translate;
